// Hand-made look-alikes of real public artworks in Vancouver, the North Shore, Burnaby, Richmond, Whistler and Victoria,
// matched by the OSM name (and sometimes the artist). Shapes, sizes, materials and poses come from the City of Vancouver
// Public Art Registry, Wikipedia, artist pages and photo descriptions (researched 2026-11-25).
// Each entry: [nameRegex, build(k, ctx) → footprint radius, fact, opts]; build adds parts to the Kit k (facing +z).
// opts: { face: 'road' (default) | 'water' | 'west' | number (fixed yaw) | 'keep' (no turn), roof: true (sits on the roof
//         of the building it is on), noPlaque: true }
import * as THREE from 'three';
import { C, U, person, bust, beast, bird, orca, pole, welcomeFigure } from './artkit.js';
import { hash2 } from './core.js';

const { BRONZE, DARKBRONZE, VERD, STEEL, GRANITE, BLACK, WHITE, GOLD, CORTEN, CONCRETE, MARBLE, CEDAR } = C;
// a stepped granite plinth (w wide, h high), returns the top height
export function plinth(k, w, h, c = GRANITE, d = w, p = k.root) {
  k.box(p, w + 0.5, 0.2, d + 0.5, c, 'stone', 0, 0.1, 0); k.box(p, w, h - 0.3, d, c, 'stone', 0, 0.2 + (h - 0.3) / 2, 0); k.box(p, w + 0.18, 0.12, d + 0.18, c, 'stone', 0, h - 0.04, 0);
  return h + 0.02;
}
const pool = (k, R, wall = 0.6, c = CONCRETE) => { k.cyl(k.root, R, R + 0.15, wall, c, 'stone', 0, wall / 2, 0, 0, 0, 0, 32); k.cyl(k.root, R - 0.3, R - 0.3, 0.04, '#2f7f99', 'steel', 0, wall + 0.01, 0, 0, 0, 0, 32); k.tor(k.root, R - 0.15, 0.17, c, 'stone', 0, wall + 0.02, 0, Math.PI / 2); return wall; };
const car = (k, p, L, c, x, y, z, ry, rz = 0) => { const n = k.node(p, x, y, z, 0, ry, rz); k.box(n, L, 0.62, 1.8, c, 'paint', 0, 0, 0); k.box(n, L * 0.5, 0.42, 1.55, '#9fb7c9', 'paint', -L * 0.05, 0.48, 0); k.box(n, L * 0.52, 0.06, 1.6, c, 'paint', -L * 0.05, 0.72, 0); for (const [wx, wz] of [[-0.32, 0.92], [0.32, 0.92], [-0.32, -0.92], [0.32, -0.92]]) k.cyl(n, 0.36, 0.36, 0.24, '#151515', 'paint', wx * L, -0.32, wz, Math.PI / 2, 0, 0, 12); return n; };
const tag = 'Real piece, modelled from photos.';

