// ---------- landmark pieces built by other modules (landmarks.js, airport.js) with this kit ----------
// Bill Reid's "The Spirit of Haida Gwaii: The Jade Canoe" (1994): a 6 m bronze canoe with a jade-green patina, crowded with
// 13 creatures of Haida myth: Raven steering at the stern, the Shaman (Kilstlaai) standing in the middle with his tall
// staff, Bear Mother and her cubs at the bow, Eagle with spread wings, Wolf, Beaver, Frog, Dogfish Woman, Mouse Woman…
export function jadeCanoe(k) {
  const c = '#2f6a52', m = 'bronze';
  k.box(k.root, 7.5, 1.0, 3.2, '#1b1c1e', 'stone', 0, 0.5, 0);
  k.lathe(k.root, [[0.02, -3.3], [0.6, -2.6], [0.95, -1.2], [1.0, 0], [0.95, 1.2], [0.6, 2.6], [0.02, 3.3]], c, m, 0, 1.55, 0, 0, 0, Math.PI / 2, 0.55, 1, 1.0, 16);   // hull along x (flattened: radial x becomes height)
  for (const s of [-1, 1]) k.shape(k.root, [[0, 0], [0.9, 0.2], [1.3, 1.3], [0.9, 1.6], [0.4, 0.7]], 0.25, c, m, s * 2.7, 1.75, 0, 0, s < 0 ? Math.PI : 0, 0, 0.85);   // upswept bow + stern
  const fig = (x, z, h, kind) => { const f = person(k, k.root, { x, z, y: 1.95, h, c, m, pose: kind === 'paddle' ? 'handsFront' : 'sitGround', ry: Math.PI / 2, girth: 1.3, hairStyle: 'bald' }); return f; };
  const sham = person(k, k.root, { x: 0, y: 1.95, h: 2.1, c, m, pose: 'oneHandFront', ry: Math.PI / 2, coat: 1, hat: 'top', girth: 1.2 }); k.cyl(sham.hands.R, 0.04, 0.05, 2.6, c, m, 0, 0.6, 0);   // the Shaman + staff
  const rv = k.node(k.root, -2.4, 2.5, 0, 0, Math.PI / 2, 0); k.sph(rv, 0.45, c, m, 0, 0.5, 0, 1, 1.2, 1); k.cone(rv, 0.16, 0.9, c, m, 0, 0.75, 0.6, Math.PI / 2, 0, 0, 8); k.cyl(rv, 0.04, 0.04, 2.2, c, m, 0.4, 0.2, -0.3, 0.6, 0, 0); k.box(rv, 0.25, 0.6, 0.06, c, m, 0.4, -0.7, -0.9, 0.6);   // Raven steering
  beast(k, k.root, { kind: 'bear', s: 0.7, c, m, x: 1.8, y: 1.95, ry: Math.PI / 2, pose: 'sit' }); beast(k, k.root, { kind: 'bear', s: 0.4, c, m, x: 2.6, y: 2.0, ry: Math.PI / 2 });
  bird(k, k.root, { kind: 'eagle', s: 2.2, c, m, pose: 'upswept', x: 1.0, y: 2.1, z: 0.3, ry: Math.PI / 2 });
  beast(k, k.root, { kind: 'coyote', s: 0.9, c, m, x: -1.0, y: 1.95, z: 0.4, ry: Math.PI / 2, pose: 'sit' });
  fig(-1.6, -0.3, 1.3, 'paddle'); fig(0.6, -0.4, 1.2, 'paddle'); fig(-0.6, 0.45, 1.1, 'sit');
  k.sph(k.root, 0.28, c, m, 0.3, 2.25, 0.6, 1.2, 0.6, 1);   // Frog
}
// Elek Imredy's "Girl in a Wetsuit" (1972): a life-size bronze diver on a rock off Stanley Park, flippers on, mask pushed
// up on her forehead, legs folded under her, looking out to sea
export function girlInWetsuit(k) {
  k.add(k.root, U.ico(1), '#4e4a44', 'stone', 0, 0.1, 0, 0, 0.4, 0, 1.7, 1.35, 1.5);
  person(k, k.root, { y: 1.25, h: 1.7, c: '#2e3a34', m: 'bronze', pose: 'sitTucked', hairStyle: 'short', hat: 'mask', flippers: 1, breasts: 1, girth: 0.92 });
}
// Vern Simpson's "Gassy Jack" (1970): copper statue of saloon keeper John Deighton standing on a whisky barrel, in a
// long coat, waistcoat and bowler hat, with mutton-chop whiskers
export function gassyJack(k) {
  k.box(k.root, 1.7, 0.4, 1.7, '#7a3a2a', 'stone', 0, 0.2, 0);
  k.lathe(k.root, [[0.5, 0], [0.6, 0.45], [0.62, 0.65], [0.6, 0.85], [0.5, 1.3]], '#5a3d26', 'wood', 0, 0.4, 0, 0, 0, 0, 1, 1, 1, 16);
  for (const y of [0.55, 1.45]) k.tor(k.root, 0.6, 0.03, '#3a3a3a', 'bronze', 0, y, 0, Math.PI / 2);
  person(k, k.root, { y: 1.72, h: 1.8, c: '#5f5030', m: 'bronze', coat: 1, suit: 1, hat: 'bowler', beard: 1, moustache: 1, girth: 1.2, pose: 'stand', poseX: { shR: 0.3, elR: 0.6, armLz: 0.2, headYaw: -0.2 } });
}
// Charles Marega's Lions Gate lions (1939): concrete couchant lions after Landseer's Trafalgar Square lions, forepaws out
export function gateLion(k) {
  k.box(k.root, 2.4, 1.6, 4.6, '#a39b88', 'stone', 0, 0.8, 0); k.box(k.root, 2.6, 0.15, 4.8, '#b3ab98', 'stone', 0, 1.62, 0);
  beast(k, k.root, { kind: 'lion', s: 1.75, y: 1.68, c: '#cfc8b8', m: 'stone', maneC: '#c4bca9', pose: 'lie', headUp: 0.25 });
}
